# System call stubs for user programs.
# x86_64: written by hand (riscv: generated by usys.pl).
# Number in rax, then int $64. C passes the 4th argument in rcx,
# the kernel reads it from r10 (as Linux, since syscall clobbers rcx).
# The kernel's return value in rax is the C return value.

#include "kernel/syscall.h"

#define STUB(sym, num) \
        .globl sym; \
sym: \
        mov $num, %eax; \
        mov %rcx, %r10; \
        int $64; \
        ret

#define SYSCALL(name) STUB(name, SYS_ ## name)

SYSCALL(fork)
SYSCALL(exit)
SYSCALL(wait)
SYSCALL(pipe)
SYSCALL(read)
SYSCALL(write)
SYSCALL(close)
SYSCALL(kill)
SYSCALL(exec)
SYSCALL(open)
SYSCALL(mknod)
SYSCALL(unlink)
SYSCALL(fstat)
SYSCALL(link)
SYSCALL(mkdir)
SYSCALL(chdir)
SYSCALL(dup)
SYSCALL(getpid)
STUB(sys_sbrk, SYS_sbrk)        # ulib.c's sbrk() and sbrklazy() wrap it
SYSCALL(pause)
SYSCALL(uptime)
SYSCALL(sync)
